"""A small built-in meal library. Ingredient groups use 'a|b' for alternatives (any one will do)."""

def M(id, name, mins, types, tags, req, opt=(), steps="", season=""):
    return dict(id=id, name=name, mins=mins, types=types.split(","), tags=set(tags.split(",")) if tags else set(),
                req=list(req), opt=list(opt), steps=steps, season=season)

